import './Form.css'
import {useState} from 'react'


const Form = ()=> {
const [title, setTitle] = useState('');
const [date, setDate] = useState('');
const [director, setDirector] = useState('');

const submitHandler = (e)=> {
    e.preventDefault();
    
}

    return(
        <Form onSubmit={submitHandler}>
            <label htmlFor="title">Title</label>
            <input id="title" placeholder="Enter Title" type="text" value={title} onChange={(e) => setTitle(e.target.value)}/>
            <label htmlFor="date">Date</label>
            <input id="date" placeholder="Enter Date" type="date" value={date} onChange={(e) => setDate(e.target.value)}/>
            <label htmlFor="director">Director</label>
            <input id="director" placeholder="Enter director Name" type="text" value={director} onChange={(e) => setDirector(e.target.value)}/>
            <button>Submit</button>
        </Form >
    )
}


export default Form;
